import{_ as d,o,c as a,a3 as e}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"贡献与规范","description":"","frontmatter":{},"headers":[],"relativePath":"dev/contributing.md","filePath":"dev/contributing.md","lastUpdated":1791133906000}'),r={name:"dev/contributing.md"};function l(i,t,n,s,c,h){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="贡献与规范" tabindex="-1">贡献与规范 <a class="header-anchor" href="#贡献与规范" aria-label="Permalink to &quot;贡献与规范&quot;">​</a></h1><p>这个框架是个人项目，但欢迎提改进、报问题、贡献 Mod。这一页讲<strong>改动应该遵守什么规范</strong>。</p><h2 id="提交改动前-先自检" tabindex="-1">提交改动前，先自检 <a class="header-anchor" href="#提交改动前-先自检" aria-label="Permalink to &quot;提交改动前，先自检&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">五条必过</p><ol><li><strong>编译通过</strong>（<code>python compile.py</code> 退出码 0）——这同时证明挂钩绑定成功</li><li><strong>汉化无损</strong>——补丁后条数不变（正常 213 条）</li><li><strong>定版 APK 未被改动</strong>——<code>final_full_cn.apk</code> 是汉化定版，框架与它完全隔离</li><li><strong>语法合规</strong>——只用 C# 3.0（见 <a href="/AtlanticFleetSite/docs/dev/cs30-limits">兼容约束</a>）</li><li><strong>异常兜底</strong>——新增可能抛异常的代码都包了 <code>try/catch</code></li></ol></div><h2 id="代码规范" tabindex="-1">代码规范 <a class="header-anchor" href="#代码规范" aria-label="Permalink to &quot;代码规范&quot;">​</a></h2><h3 id="命名" tabindex="-1">命名 <a class="header-anchor" href="#命名" aria-label="Permalink to &quot;命名&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>约定</th><th>例子</th></tr></thead><tbody><tr><td>框架类</td><td><code>Mod</code> 前缀</td><td><code>ModConfig</code> / <code>ModLoader</code></td></tr><tr><td>参数键</td><td><code>组.动作</code> 小写点分</td><td><code>gun.damageMul</code></td></tr><tr><td>常量</td><td>大写下划线</td><td><code>PREFIX</code> / <code>IMPORT_DIR</code></td></tr><tr><td>私有字段</td><td>下划线前缀（按现有风格）</td><td><code>_overrides</code></td></tr></tbody></table><h3 id="铁律清单-每条都是踩坑换来的" tabindex="-1">铁律清单（每条都是踩坑换来的） <a class="header-anchor" href="#铁律清单-每条都是踩坑换来的" aria-label="Permalink to &quot;铁律清单（每条都是踩坑换来的）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>铁律</th><th>为什么</th></tr></thead><tbody><tr><td>1</td><td><strong>参数持久化：实验性/危险参数绝不跨会话保存</strong></td><td>尤其 <code>sandbox.timeScale</code>，否则玩家陷入「我什么都没调却全变了」</td></tr><tr><td>2</td><td><strong>倍速暂停档绝不进快捷循环</strong></td><td>误触到 <code>x0</code> 会让全部协程冻结，像死机</td></tr><tr><td>3</td><td><strong>改 <code>GUI.skin</code> 必须成对还原</strong></td><td>否则永久污染全局界面</td></tr><tr><td>4</td><td><strong>每个标签页都要 <code>BeginScrollView</code></strong></td><td>内容必然溢出，溢出即「看不见又滚不动」</td></tr><tr><td>5</td><td><strong>破坏性按钮两段确认，确认态要清零</strong></td><td>防残留误点</td></tr><tr><td>6</td><td><strong>触控判定阈值按屏宽比例取</strong></td><td>固定像素在手机上必被抖动突破</td></tr><tr><td>7</td><td><strong>诊断日志必须落盘</strong></td><td>内存日志游戏一关就没了</td></tr><tr><td>8</td><td><strong>成组预设值必须机器校验边界</strong></td><td>超硬边界会被静默钳制，最难查</td></tr></tbody></table><h2 id="贡献-mod-的规范" tabindex="-1">贡献 Mod 的规范 <a class="header-anchor" href="#贡献-mod-的规范" aria-label="Permalink to &quot;贡献 Mod 的规范&quot;">​</a></h2><p>比贡献代码更常见、也更值得做的事：<strong>做一个 Mod 分享出来</strong>。</p><h3 id="质量要求" tabindex="-1">质量要求 <a class="header-anchor" href="#质量要求" aria-label="Permalink to &quot;质量要求&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td><code>modName</code></td><td><strong>必需</strong>，写清楚是什么</td></tr><tr><td><code>author</code></td><td>建议填，方便别人找你</td></tr><tr><td><code>version</code></td><td>建议填，便于追踪</td></tr><tr><td>参数值</td><td>别超硬边界（对照 <a href="/AtlanticFleetSite/docs/dev/param-keys">参数键全表</a>）</td></tr><tr><td>舰级 / 编队名</td><td>起不重复的名字，避免与他人冲突</td></tr></tbody></table><h3 id="发布到仓库" tabindex="-1">发布到仓库 <a class="header-anchor" href="#发布到仓库" aria-label="Permalink to &quot;发布到仓库&quot;">​</a></h3><p>打开 <a href="https://atlanticfleet.asia/mods/" target="_blank" rel="noreferrer">Mod 仓库</a> 的上传区，填作者、拖入（或粘贴）<code>mod.json</code>，点「提交审核」。管理员过审后自动上架。</p><p>详细步骤见 <a href="/AtlanticFleetSite/docs/repo/publish">上传你的 Mod（作者）</a>。</p><h2 id="报告问题" tabindex="-1">报告问题 <a class="header-anchor" href="#报告问题" aria-label="Permalink to &quot;报告问题&quot;">​</a></h2><p>报问题时，<strong>日志是关键证据</strong>。请附上：</p><ol><li>游戏内「小u」→「日志」页 →「<strong>复制全部日志</strong>」的完整内容</li><li>你的设备信息（日志里已含：屏幕 / DPI / 系统版本 / 内存）</li><li>复现步骤（做了什么、期望什么、实际什么）</li><li>装了哪些 Mod（如有）</li></ol><div class="tip custom-block"><p class="custom-block-title">不要只贴现象</p><p>「打不开」「没反应」这类描述定位不了问题。日志里的一行错误码，比十句现象描述都有用。</p></div><h2 id="已知限制-不要当-bug-报的" tabindex="-1">已知限制（不要当 bug 报的） <a class="header-anchor" href="#已知限制-不要当-bug-报的" aria-label="Permalink to &quot;已知限制（不要当 bug 报的）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>说明</th></tr></thead><tbody><tr><td>不支持互联网联机</td><td>受纯客户端重编译约束，只能同设备热座</td></tr><tr><td>无 Harmony</td><td>有意不做，用源码内挂钩（见 <a href="/AtlanticFleetSite/docs/roadmap">路线图</a>）</td></tr><tr><td>游戏内无 Mod 市场</td><td>有意不做，用网页版仓库替代</td></tr><tr><td>真机兼容矩阵</td><td>需真实设备，本机无模拟器，靠设备自检 + 回传</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>架构与目录 → <a href="/AtlanticFleetSite/docs/dev/codebase">框架源码结构</a></li><li>改前必读 → <a href="/AtlanticFleetSite/docs/dev/cs30-limits">C# 3.0 兼容约束</a></li><li>未来规划 → <a href="/AtlanticFleetSite/docs/roadmap">路线图</a></li></ul>',24)])])}const u=d(r,[["render",l]]);export{g as __pageData,u as default};
